const CANCELLED_SEASON = "2020-2021";

function ordinal(n) {
  const s = ["th", "st", "nd", "rd"];
  const v = n % 100;
  return `${n}${s[(v - 20) % 10] || s[v] || s[0]}`;
}
function isCancelled(season) {
  return DIVISIONS[season] === null;
}
function divisionLabel(season) {
  const d = DIVISIONS[season];
  if (d === null || d === undefined) return null;
  return `${ordinal(d)} Division`;
}

